-- Car documents: registration certificate, insurance, road tax, revisione and
-- expenses, under one CAR_DOCUMENT type. Every template asks for the car with
-- the same keys (registration_number, vin, make, commercial_name), so each one
-- is matched to its car by plate or VIN; the registration certificate asks for
-- the fields of the carta di circolazione with the template keys of
-- VEHICLE_FIELD_DEFINITIONS (libs/contracts), each described with its EU code.
-- These mirror the life-island-docs car blueprints (cars/*.schema.json).
-- A registration certificate always waits for review (reason VEHICLE_DATA).
-- The subtypes go below CAR_DOCUMENT; if you already had a category titled
-- "Car document" (so CAR_DOCUMENT is skipped) they stay top-level instead.
-- Data only; a category with the same id or title that you created already is
-- kept as it is. Rollback: drizzle/rollback/0013_car_document_categories.down.sql.
WITH inserted AS (
  INSERT INTO "ingestion"."document_categories" ("id", "title", "description", "template_json", "parent_id", "dimension") VALUES
  ('CAR_DOCUMENT', 'Car document', 'A document about one of your cars: its registration certificate (carta di circolazione / documento unico), insurance, road tax (bollo), revisione, or any expense for it (fuel, service, repairs, tyres, tolls, fines). It is matched to the car by its plate before it counts.', '{"fields":[{"key":"registration_number","label":"Number plate","type":"string","description":"Targa of the car this document is about, without spaces, upper-case (AB123CD). Null when it prints none (most fuel receipts)","required":false},{"key":"vin","label":"VIN","type":"string","description":"Numero di telaio, if printed","required":false},{"key":"make","label":"Make","type":"string","description":"Marca of the car, if printed (FIAT)","required":false},{"key":"commercial_name","label":"Model","type":"string","description":"Model of the car, if printed (PANDA)","required":false}]}'::jsonb, NULL, 'DOCUMENT_TYPE')
  ON CONFLICT DO NOTHING
  RETURNING "id", "title", "parent_id", "dimension"
)
-- Modules that keep their own copy of the categories (review inbox, Home, People, Cars) learn them from category.changed@1.
INSERT INTO "ingestion"."outbox" (event_type, payload)
SELECT 'category.changed@1',
       jsonb_build_object(
         'id', i.id,
         'title', i.title,
         'parentId', i.parent_id,
         'dimension', i.dimension,
         'deleted', false,
         'changedAt', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
       )
  FROM inserted i;--> statement-breakpoint
WITH inserted AS (
  INSERT INTO "ingestion"."document_categories" ("id", "title", "description", "template_json", "parent_id", "dimension")
  SELECT v.id, v.title, v.description, v.template_json,
         (SELECT p.id FROM "ingestion"."document_categories" p WHERE p.id = 'CAR_DOCUMENT'),
         v.dimension::"ingestion"."category_dimension"
    FROM (VALUES
    ('VEHICLE_REGISTRATION', 'Registration certificate', 'The carta di circolazione (libretto) or the documento unico di circolazione e di proprietà: every field next to its EU code (A, B, C.1, D.1, E, F.1, J, K, P.1, V.7...). Its car data is checked against the car before it is kept.', '{"fields":[{"key":"registration_number","label":"Number plate","type":"string","description":"Field A of the card: Targa, without spaces, upper-case (AB123CD)","required":true},{"key":"first_registration_date","label":"First registration","type":"date","description":"Field B of the card: Data di prima immatricolazione","required":true},{"key":"registration_date","label":"Registration this card refers to","type":"date","description":"Field I of the card: Data dell''immatricolazione a cui si riferisce la carta","required":false},{"key":"registration_valid_until","label":"Valid until","type":"date","description":"Field H of the card: Durata di validità, only on temporary registrations","required":false},{"key":"holder_name","label":"Holder","type":"string","description":"Field C.1.1 of the card: Intestatario: C.1.1 surname or company name and C.1.2 first name, as printed","required":false},{"key":"holder_tax_code","label":"Holder tax code","type":"string","description":"Field C.1 of the card: Codice fiscale or VAT number of the holder, if printed","required":false},{"key":"holder_address","label":"Holder address","type":"string","description":"Field C.1.3 of the card: Indirizzo dell''intestatario, as printed","required":false},{"key":"owner_name","label":"Owner","type":"string","description":"Field C.2.1 of the card: Proprietario (C.2.1 and C.2.2), only when printed apart from the holder","required":false},{"key":"holder_is_owner","label":"Holder is the owner","type":"enum","description":"Field C.4 of the card: C.4 a) owner, b) not_owner, c) not_identified","required":false,"options":["owner","not_owner","not_identified"]},{"key":"make","label":"Make","type":"string","description":"Field D.1 of the card: Marca (FIAT)","required":true},{"key":"type_variant_version","label":"Type, variant, version","type":"string","description":"Field D.2 of the card: Tipo, variante, versione as printed","required":false},{"key":"commercial_name","label":"Model","type":"string","description":"Field D.3 of the card: Denominazione commerciale (PANDA)","required":false},{"key":"vin","label":"VIN (chassis number)","type":"string","description":"Field E of the card: Numero di telaio, 17 characters","required":true},{"key":"technically_permissible_max_mass_kg","label":"Max laden mass (technical)","type":"integer","description":"Field F.1 of the card: Massa massima a carico tecnicamente ammissibile","required":false,"unit":"kg"},{"key":"permissible_max_mass_kg","label":"Max laden mass in service","type":"integer","description":"Field F.2 of the card: Massa massima a carico ammissibile in servizio","required":false,"unit":"kg"},{"key":"permissible_combination_max_mass_kg","label":"Max mass with trailer","type":"integer","description":"Field F.3 of the card: Massa massima dell''insieme","required":false,"unit":"kg"},{"key":"mass_in_service_kg","label":"Mass in service","type":"integer","description":"Field G of the card: Massa del veicolo in servizio","required":false,"unit":"kg"},{"key":"category","label":"Category","type":"enum","description":"Field J of the card: Categoria (M1 for a car)","required":false,"options":["M1","M1G","M2","M3","N1","N1G","N2","N3","O1","O2","O3","O4","L1e","L2e","L3e","L4e","L5e","L6e","L7e","T","other"]},{"key":"kind","label":"Kind of vehicle","type":"enum","description":"Field J.1 of the card: First half of J.1: AUTOVETTURA is car, AUTOCARRO goods_vehicle","required":false,"options":["car","goods_vehicle","special_use_vehicle","motorcycle","moped","motor_caravan","trailer","quadricycle","other"]},{"key":"use","label":"Use","type":"enum","description":"Field J.1 of the card: Second half of J.1: USO PROPRIO is own_use, USO DI TERZI third_party_use","required":false,"options":["own_use","third_party_use","rental_without_driver","rental_with_driver","taxi","other"]},{"key":"bodywork","label":"Bodywork","type":"string","description":"Field J.2 of the card: Carrozzeria code (AA saloon, AB hatchback, AC station wagon, AF multi-purpose)","required":false},{"key":"type_approval_number","label":"Type-approval number","type":"string","description":"Field K of the card: Numero di omologazione (e3*2007/46*0064*25)","required":false},{"key":"axle_count","label":"Axles","type":"integer","description":"Field L of the card: Numero di assi","required":false},{"key":"wheelbase_mm","label":"Wheelbase","type":"integer","description":"Field M of the card: Interasse","required":false,"unit":"mm"},{"key":"braked_trailer_max_kg","label":"Braked trailer","type":"integer","description":"Field O.1 of the card: Massa rimorchiabile frenata","required":false,"unit":"kg"},{"key":"unbraked_trailer_max_kg","label":"Unbraked trailer","type":"integer","description":"Field O.2 of the card: Massa rimorchiabile non frenata","required":false,"unit":"kg"},{"key":"engine_capacity_cc","label":"Engine capacity","type":"integer","description":"Field P.1 of the card: Cilindrata","required":false,"unit":"cm³"},{"key":"max_net_power_kw","label":"Power","type":"number","description":"Field P.2 of the card: Potenza massima netta","required":false,"unit":"kW"},{"key":"fuel","label":"Fuel","type":"enum","description":"Field P.3 of the card: Alimentazione: BENZINA petrol, GASOLIO diesel, BENZ/GPL petrol_lpg, BENZ/METANO petrol_cng, ELETTRICA electric","required":false,"options":["petrol","diesel","lpg","cng","lng","electric","hydrogen","petrol_lpg","petrol_cng","hybrid_petrol","hybrid_diesel","plug_in_hybrid_petrol","plug_in_hybrid_diesel","other"]},{"key":"rated_speed_rpm","label":"Rated speed","type":"integer","description":"Field P.4 of the card: Regime nominale","required":false,"unit":"rpm"},{"key":"engine_code","label":"Engine code","type":"string","description":"Field P.5 of the card: Numero o tipo del motore","required":false},{"key":"colour","label":"Colour","type":"string","description":"Field R of the card: Colore, as printed","required":false},{"key":"seat_count","label":"Seats","type":"integer","description":"Field S.1 of the card: Posti a sedere, driver included","required":false},{"key":"max_speed_kmh","label":"Top speed","type":"integer","description":"Field T of the card: Velocità massima","required":false,"unit":"km/h"},{"key":"co2_g_km","label":"CO2","type":"number","description":"Field V.7 of the card: Emissioni di CO2","required":false,"unit":"g/km"},{"key":"combined_fuel_consumption","label":"Combined consumption","type":"number","description":"Field V.8 of the card: Consumo in ciclo misto","required":false,"unit":"l/100 km"},{"key":"emission_class","label":"Environmental class","type":"string","description":"Field V.9 of the card: Classe ambientale as printed (715/2007*2018/1832AP EURO 6D)","required":false},{"key":"fuel_tank_capacity_l","label":"Fuel tank","type":"number","description":"Field W of the card: Capacità del serbatoio","required":false,"unit":"l"},{"key":"document_number","label":"Document number","type":"string","description":"Number of the carta di circolazione or documento unico, as printed","required":false},{"key":"issue_date","label":"Issue date","type":"date","description":"Date the certificate was issued (data di rilascio)","required":false}]}'::jsonb, 'DOCUMENT_TYPE'),
    ('CAR_INSURANCE', 'Car insurance', 'A motor insurance policy or certificate (polizza RCA auto) with its extra cover: insurer, policy number, start and end of the cover, bonus-malus class and premium.', '{"fields":[{"key":"registration_number","label":"Number plate","type":"string","description":"Targa of the car this document is about, without spaces, upper-case (AB123CD). Null when it prints none (most fuel receipts)","required":true},{"key":"vin","label":"VIN","type":"string","description":"Numero di telaio, if printed","required":false},{"key":"make","label":"Make","type":"string","description":"Marca of the car, if printed (FIAT)","required":false},{"key":"commercial_name","label":"Model","type":"string","description":"Model of the car, if printed (PANDA)","required":false},{"key":"insurer","label":"Insurer","type":"string","description":"Compagnia assicurativa, as printed","required":false},{"key":"policy_number","label":"Policy number","type":"string","description":"Numero di polizza","required":false},{"key":"policyholder","label":"Policyholder","type":"string","description":"Contraente, as printed","required":false},{"key":"start_date","label":"Start date","type":"date","description":"Effetto / decorrenza of the cover","required":false},{"key":"end_date","label":"End date","type":"date","description":"Scadenza: the date the cover ends","required":true},{"key":"payment_frequency","label":"Payment frequency","type":"enum","description":"Frazionamento del premio","required":false,"options":["annual","semiannual","quarterly","monthly","single"]},{"key":"next_installment_date","label":"Next instalment","type":"date","description":"Scadenza della prossima rata, when the premium is split","required":false},{"key":"cu_class","label":"Bonus-malus class","type":"integer","description":"Classe di merito CU (1 to 18)","required":false},{"key":"coverages","label":"Cover","type":"string","description":"Garanzie, comma separated: RCA, incendio e furto, kasko, cristalli, assistenza stradale...","required":false},{"key":"total_amount","label":"Premium","type":"amount","description":"Premio totale of the period","required":true},{"key":"payment_date","label":"Payment date","type":"date","description":"Data di pagamento / quietanza","required":false}]}'::jsonb, 'DOCUMENT_TYPE'),
    ('ROAD_TAX', 'Road tax', 'The receipt of the tassa automobilistica (bollo auto) paid to the Regione, through pagoPA, ACI, a tobacconist or the bank: plate, expiry month, months of validity and amount.', '{"fields":[{"key":"registration_number","label":"Number plate","type":"string","description":"Targa of the car this document is about, without spaces, upper-case (AB123CD). Null when it prints none (most fuel receipts)","required":true},{"key":"region","label":"Region","type":"string","description":"Regione the tax is paid to","required":false},{"key":"receipt_number","label":"Receipt number","type":"string","description":"Numero ricevuta, IUV or codice avviso pagoPA","required":false},{"key":"payment_date","label":"Payment date","type":"date","description":"Data di pagamento","required":false},{"key":"expiry_month","label":"Expiry month","type":"string","description":"Mese di scadenza as YYYY-MM: the last month this payment covers","required":true,"pattern":"^[0-9]{4}-(0[1-9]|1[0-2])$"},{"key":"validity_months","label":"Months of validity","type":"integer","description":"Mesi di validità (12 most often)","required":false},{"key":"power_kw","label":"Power","type":"number","description":"kW the tax was computed on, if printed","required":false,"unit":"kW"},{"key":"total_amount","label":"Total paid","type":"amount","description":"Totale pagato, penalty and fees included","required":true},{"key":"exempt","label":"Exempt","type":"boolean","description":"True when the receipt is an esenzione","required":false}]}'::jsonb, 'DOCUMENT_TYPE'),
    ('VEHICLE_INSPECTION', 'Vehicle inspection', 'The report or receipt of a revisione at a centro revisioni or the Motorizzazione: date, outcome, km read and amount.', '{"fields":[{"key":"registration_number","label":"Number plate","type":"string","description":"Targa of the car this document is about, without spaces, upper-case (AB123CD). Null when it prints none (most fuel receipts)","required":true},{"key":"vin","label":"VIN","type":"string","description":"Numero di telaio, if printed","required":false},{"key":"inspection_centre","label":"Inspection centre","type":"string","description":"Centro revisioni or Motorizzazione office, as printed","required":false},{"key":"report_number","label":"Report number","type":"string","description":"Numero del certificato / protocollo","required":false},{"key":"inspection_date","label":"Inspection date","type":"date","description":"Data della revisione","required":true},{"key":"outcome","label":"Outcome","type":"enum","description":"Esito: regolare is passed, ripetere is repeat, sospeso is suspended","required":true,"options":["passed","repeat","suspended"]},{"key":"odometer_km","label":"Odometer","type":"integer","description":"Km rilevati","required":false,"unit":"km"},{"key":"next_due_date","label":"Next revisione by","type":"date","description":"Prossima revisione entro, only if printed","required":false},{"key":"total_amount","label":"Total paid","type":"amount","description":"Totale pagato","required":false}]}'::jsonb, 'DOCUMENT_TYPE'),
    ('VEHICLE_EXPENSE', 'Car expense', 'Any other cost of a car: a fuel or charging receipt, a garage invoice (tagliando, repair, tyres, body work), car wash, tolls, parking, accessories or a fine.', '{"fields":[{"key":"registration_number","label":"Number plate","type":"string","description":"Targa of the car this document is about, without spaces, upper-case (AB123CD). Null when it prints none (most fuel receipts)","required":false},{"key":"expense_kind","label":"Kind","type":"enum","description":"fuel, ev_charging, scheduled_service (tagliando), repair, tyres, body_work, car_wash, toll, parking, accessories, fine or other","required":true,"options":["fuel","ev_charging","scheduled_service","repair","tyres","body_work","car_wash","toll","parking","accessories","fine","other"]},{"key":"supplier","label":"Supplier","type":"string","description":"Fuel station, garage or seller, as printed","required":false},{"key":"document_number","label":"Document number","type":"string","description":"Fattura or scontrino number","required":false},{"key":"expense_date","label":"Date","type":"date","description":"Date of the receipt or invoice","required":true},{"key":"odometer_km","label":"Odometer","type":"integer","description":"Km printed on the receipt or invoice","required":false,"unit":"km"},{"key":"fuel","label":"Fuel","type":"enum","description":"Fuel bought, on a fuel receipt","required":false,"options":["petrol","diesel","lpg","cng","lng","electric","hydrogen","petrol_lpg","petrol_cng","hybrid_petrol","hybrid_diesel","plug_in_hybrid_petrol","plug_in_hybrid_diesel","other"]},{"key":"litres","label":"Litres","type":"number","description":"Litres (kg for CNG) bought","required":false,"unit":"l"},{"key":"price_per_unit","label":"Price per litre","type":"number","description":"€ per litre (or kg, or kWh)","required":false,"unit":"€"},{"key":"kwh","label":"Energy charged","type":"number","description":"kWh, on a charging receipt","required":false,"unit":"kWh"},{"key":"next_service_date","label":"Next service by","type":"date","description":"Prossimo tagliando entro, only if printed","required":false},{"key":"next_service_km","label":"Next service at","type":"integer","description":"Prossimo tagliando ai km, only if printed","required":false,"unit":"km"},{"key":"total_amount","label":"Total paid","type":"amount","description":"Totale pagato","required":true}]}'::jsonb, 'DOCUMENT_TYPE')
    ) AS v (id, title, description, template_json, dimension)
  ON CONFLICT DO NOTHING
  RETURNING "id", "title", "parent_id", "dimension"
)
-- Modules that keep their own copy of the categories (review inbox, Home, People, Cars) learn them from category.changed@1.
INSERT INTO "ingestion"."outbox" (event_type, payload)
SELECT 'category.changed@1',
       jsonb_build_object(
         'id', i.id,
         'title', i.title,
         'parentId', i.parent_id,
         'dimension', i.dimension,
         'deleted', false,
         'changedAt', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
       )
  FROM inserted i;
